package com.hbm.machine.generator.stirling;
import com.hbm.damage.HbmDamageSources;import com.hbm.entity.projectile.EntityThrowableInterp;import com.hbm.hazard.HbmHazards;import com.hbm.machine.generator.steamengine.SteamEngineContent;import com.hbm.weapon.sedna.death.DeathParticlePacket;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.syncher.*;import net.minecraft.sounds.SoundEvents;import net.minecraft.sounds.SoundSource;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.phys.*;
/** Actual source entity_stray_cog, with shared true throwable flight, block bounce, rubble damage and gear recovery. */
public final class StrayCogEntity extends EntityThrowableInterp implements com.hbm.entity.LegacyTrackingRange {
 private static final EntityDataAccessor<Integer> ORIENTATION=SynchedEntityData.defineId(StrayCogEntity.class,EntityDataSerializers.INT),META=SynchedEntityData.defineId(StrayCogEntity.class,EntityDataSerializers.INT);private boolean sourceNullTile=true;
 public StrayCogEntity(EntityType<? extends StrayCogEntity> type,Level level){super(type,level);}public StrayCogEntity(Level level,double x,double y,double z){this(StirlingContent.COG.get(),level);setPos(x,y,z);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder builder){super.defineSynchedData(builder);builder.define(ORIENTATION,0);builder.define(META,0);}public StrayCogEntity orientation(int orientation){entityData.set(ORIENTATION,orientation);return this;}public StrayCogEntity metadata(int metadata){entityData.set(META,metadata);return this;}public int orientation(){return entityData.get(ORIENTATION);}public int metadata(){return entityData.get(META);}
 @Override public int legacyTrackingRange(){return 1000;}@Override public boolean shouldRenderAtSqrDistance(double distance){return true;}@Override public boolean isPickable(){return true;}
 @Override public InteractionResult interact(Player player,InteractionHand hand){if(!level().isClientSide){var gear=new ItemStack(SteamEngineContent.GEAR.get());gear.set(HbmHazards.LEGACY_METADATA.get(),metadata());if(player.getInventory().add(gear))discard();player.containerMenu.broadcastChanges();}return InteractionResult.PASS;}
 @Override protected void onImpact(HitResult hit){if(hit instanceof EntityHitResult impact&&impact.getEntity().isAlive()){var target=impact.getEntity();target.hurt(HbmDamageSources.source(level(),HbmDamageSources.rubble),1000);if(!target.isAlive()&&target instanceof LivingEntity){DeathParticlePacket.giblets(target,0,5);level().playSound(null,target.getX(),target.getY(),target.getZ(),SoundEvents.ZOMBIE_BREAK_WOODEN_DOOR,SoundSource.HOSTILE,2,.95F+level().random.nextFloat()*.2F);}}if(tickCount>1&&hit instanceof BlockHitResult block){int orientation=orientation();if(orientation<6){if(getDeltaMovement().length()<.75){orientation(orientation+6);orientation+=6;}else{var side=block.getDirection();setDeltaMovement(getDeltaMovement().multiply(1-Math.abs(side.getStepX())*2,1-Math.abs(side.getStepY())*2,1-Math.abs(side.getStepZ())*2));level().explode(this,getX(),getY(),getZ(),3,false,Level.ExplosionInteraction.NONE);if(level().getBlockState(block.getBlockPos()).getBlock().getExplosionResistance()<50)level().destroyBlock(block.getBlockPos(),false,this);}}if(orientation>=6){setDeltaMovement(Vec3.ZERO);inGround=true;}}}
 @Override public void tick(){if(!level().isClientSide&&inGround&&sourceNullTile){baseTick();if(throwableShake>0)throwableShake--;inGround=false;setDeltaMovement(getDeltaMovement().multiply(random.nextFloat()*.2F,random.nextFloat()*.2F,random.nextFloat()*.2F));ticksInGround=ticksInAir=0;return;}super.tick();}
 @Override public double getGravityVelocity(){return inGround?0:.03;}@Override protected int groundDespawn(){return 0;}
 @Override protected void addAdditionalSaveData(CompoundTag tag){super.addAdditionalSaveData(tag);tag.putInt("rot",orientation());tag.putInt("meta",metadata());}@Override protected void readAdditionalSaveData(CompoundTag tag){var stored=tag;if(tag.getInt("xTile")==-1&&tag.getInt("yTile")==-1&&tag.getInt("zTile")==-1){stored=tag.copy();stored.putInt("yTile",level().getMinBuildHeight()-1);}super.readAdditionalSaveData(stored);orientation(tag.getInt("rot"));metadata(tag.getInt("meta"));sourceNullTile=false;}
}
